    @Override public String loaiTaiLieu()        { return "SÁCH GIẤY"; }
    @Override public int soNgayMuonToiDa()       { return 14; }
    @Override public BigDecimal phiPhatMoiNgay() { return new BigDecimal("5000"); }

    public int getSoTrang() { return soTrang; }
}
