### 5.5 Bước 4 — Service: nơi polymorphism tỏa sáng

```java
package thuvien;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

public class ThuVienService {

    // ENCAPSULATION: private final, người ngoài không đụng được list gốc
    private final List<TaiLieu> khoTaiLieu = new ArrayList<>();

    public void themTaiLieu(TaiLieu taiLieu) {
        if (taiLieu == null) {
            throw new IllegalArgumentException("Tài liệu không được null");
        }
        khoTaiLieu.add(taiLieu);
    }

    /**
     * POLYMORPHISM: tham số là TaiLieu (kiểu tổng quát).
     * Method này KHÔNG hề biết SachGiay, Ebook hay Dvd tồn tại.
     * Thêm loại tài liệu mới → KHÔNG cần sửa dòng nào ở đây.
     */
    public void muonTaiLieu(String maTaiLieu) {
        TaiLieu tl = timTheoMa(maTaiLieu)
            .orElseThrow(() -> new IllegalArgumentException("Không tìm thấy: " + maTaiLieu));

        tl.muon();                             // → chạy quy tắc riêng của từng loại
        System.out.println("Đã cho mượn " + tl.getTieuDe()
                + " trong " + tl.soNgayMuonToiDa() + " ngày");
    }

    public BigDecimal traTaiLieu(String maTaiLieu, int soNgayTre) {
        TaiLieu tl = timTheoMa(maTaiLieu)
            .orElseThrow(() -> new IllegalArgumentException("Không tìm thấy: " + maTaiLieu));

        tl.tra();
        BigDecimal phat = tl.tinhTienPhat(soNgayTre);   // default method của interface
        System.out.println("Trả " + tl.getTieuDe() + ", tiền phạt: " + phat + "đ");
        return phat;
    }

    // Trả Optional, KHÔNG trả null (chuẩn CLAUDE.md)
    public Optional<TaiLieu> timTheoMa(String ma) {
        return khoTaiLieu.stream()
                .filter(t -> t.getMaTaiLieu().equals(ma))
                .findFirst();
    }

    public void inToanBoKho() {
        System.out.println("=== KHO TÀI LIỆU (" + khoTaiLieu.size() + " mục) ===");
        for (TaiLieu tl : khoTaiLieu) {
            tl.hienThi();                      // ⭐ MỘT lời gọi → BA hành vi khác nhau
        }
    }

    // ENCAPSULATION: trả bản chỉ-đọc, tránh rò rỉ tham chiếu
    public List<TaiLieu> getKhoTaiLieu() {
        return Collections.unmodifiableList(khoTaiLieu);
    }
}
```

### 5.6 Bước 5 — Chạy thử

```java
package thuvien;

public class Main {
    public static void main(String[] args) {
        ThuVienService tv = new ThuVienService();

        tv.themTaiLieu(new SachGiay("S001", "Clean Code", "Robert Martin", 464));
        tv.themTaiLieu(new Ebook("E001", "Effective Java", "Joshua Bloch", 12.5));
        tv.themTaiLieu(new Dvd("D001", "The Matrix", "Wachowski", 136));

        tv.inToanBoKho();

        System.out.println("\n=== MƯỢN ===");
        tv.muonTaiLieu("S001");
        tv.muonTaiLieu("E001");

        System.out.println("\n=== MƯỢN LẦN 2 ===");
        tv.muonTaiLieu("E001");                 // Ebook cho phép nhiều bản → OK
        try {
            tv.muonTaiLieu("S001");             // Sách giấy chỉ có 1 bản → lỗi
        } catch (IllegalStateException e) {
            System.out.println("LỖI: " + e.getMessage());
        }

        System.out.println("\n=== TRẢ (trễ 3 ngày) ===");
        tv.traTaiLieu("S001", 3);
        tv.traTaiLieu("E001", 3);

        System.out.println("\n=== METHOD RIÊNG (cần downcasting) ===");
        tv.timTheoMa("E001").ifPresent(tl -> {
            if (tl instanceof Ebook ebook) {    // pattern matching Java 16+
                ebook.taiVe();
            }
        });
    }
}
