    public TapChi(String ma, String tieuDe, String nxb, int soPhatHanh) {
        super(ma, tieuDe, nxb);
        this.soPhatHanh = soPhatHanh;
    }

    @Override public String loaiTaiLieu()        { return "TẠP CHÍ"; }
    @Override public int soNgayMuonToiDa()       { return 5; }
    @Override public BigDecimal phiPhatMoiNgay() { return new BigDecimal("2000"); }
}
```

```java
tv.themTaiLieu(new TapChi("T001", "Tia Sáng", "NXB KHCN", 245));
tv.inToanBoKho();       // Tự động hiển thị đúng, không sửa gì
